def _prune(d: Dict[str, Any]) -> Dict[str, Any]:
    """Drop absent values: a tool distinguishes an omitted key from an explicit null."""
    return {k: v for k, v in d.items() if v is not None}


def _camel_keys(d: Dict[str, Any]) -> Dict[str, Any]:
    """Options arrive as Python kwargs (snapshot_id=…); tool arguments are camelCase (snapshotId)."""
    return {re.sub(r"_([a-z0-9])", lambda m: m.group(1).upper(), k): v for k, v in d.items()}


class Threads:
    """Agent threads — the unit of work."""

    def __init__(self, t: Any) -> None:
        self._t = t

    def list(self) -> Any:
        """Your threads."""
        a = {}
        return self._t.call("list_threads", a)

    def get(self, thread_id: str) -> Any:
        """One thread's detail."""
        a = _prune({"threadId": thread_id})
        return self._t.call("get_thread", a)

    def create(self, **opts: Any) -> Any:
        """Spawn a thread: {intent, snapshotId?, …}, or {agentless: true, snapshotId} for a world you drive."""
        a = {}
        a.update(_camel_keys(opts))
        return self._t.call("create_thread", a)

    def send(self, thread_id: str, text: str) -> Any:
        """Message a thread."""
        a = _prune({"threadId": thread_id, "text": text})
        return self._t.call("send_message", a)

    def events(self, thread_id: str) -> Any:
        """A thread's event log."""
        a = _prune({"threadId": thread_id})
        return self._t.call("thread_events", a)

    def kill(self, thread_id: str) -> Any:
        """Stop a thread's run (the thread itself persists)."""
        a = _prune({"pid": ("thread:" + thread_id if thread_id is not None else None)})
        return self._t.call("kill_process", a)


class Embodiments:
    """Computers, cameras, robots and sims attached to a thread."""

    def __init__(self, t: Any) -> None:
        self._t = t

    def list(self) -> Any:
        """Attached embodiments."""
        a = {}
        return self._t.call("list_embodiments", a)

    def launch(self, **opts: Any) -> Any:
        """Launch an embodiment into the thread: {kind?, snapshotId?, fromSnapshotId?}."""
        a = {}
        a.update(_camel_keys(opts))
        a = self._t._with_thread(a)
        return self._t.call("launch_embodiment", a)

    def observe(self, **opts: Any) -> Any:
        """The thread's observation plane: stream channels and the latest frame per embodiment."""
        a = {}
        a.update(_camel_keys(opts))
        a = self._t._with_thread(a)
        return self._t.call("observe", a)

    def controls(self, embodiment_id: str, thread_id: Optional[str] = None) -> Any:
        """What an embodiment can be driven with right now: channels, actions, payload schemas."""
        a = _prune({"embodimentId": embodiment_id, "threadId": thread_id})
        a = self._t._with_thread(a)
        return self._t.call("list_controls", a)

    def act(self, embodiment_id: str, action: str, payload: Optional[Dict[str, Any]] = None, thread_id: Optional[str] = None) -> Any:
        """Drive an embodiment with one declared action (see controls)."""
        a = _prune({"embodimentId": embodiment_id, "action": action, "payload": payload, "threadId": thread_id})
        a = self._t._with_thread(a)
        return self._t.call("act", a)

    def describe(self, thread_id: Optional[str] = None) -> Any:
        """The live sim/robot world: robots, objects and poses the runtime reports."""
        a = _prune({"threadId": thread_id})
        a = self._t._with_thread(a)
        return self._t.call("describe_world", a)


class Memory:
    """The agent's durable memory: markdown files under memories/ in the thread's drive."""

    def __init__(self, t: Any) -> None:
        self._t = t

    def search(self, query: str) -> Any:
        """Recall by query (the drive's content index over memories/)."""
        a = _prune({"q": query})
        return self._t.call("memory_search", a)

    def remember(self, **opts: Any) -> Any:
        """Write a memory file."""
        a = {}
